<template>
  <view class="page">
    <view class="topbar"><view><text class="eyebrow">CAMPAIGN CENTER</text><text class="title">活动与套餐</text></view><view class="bell" @tap="goNotifications"><text class="bell-glyph iconfont icon-lingdang-xianxing"/><text class="unread-dot"/></view></view>
    <view class="content">
      <button class="create" @tap="createCampaign"><text>＋</text>新建套餐</button>
      <view class="search"><text>⌕</text><input v-model.trim="keyword" maxlength="30" placeholder="搜索套餐名称" confirm-type="search"/></view>
      <view class="tabs"><text :class="{active:filter==='all'}" @tap="setFilter('all')">全部 <i>{{ counts.all }}</i></text><text :class="{active:filter==='offline'}" @tap="setFilter('offline')">下架 <i>{{ counts.offline }}</i></text><view class="more" :class="{active:['reviewing','rejected'].includes(filter),opened:filterOpen}" @tap="filterOpen=!filterOpen"><text>{{ filterLabel }}</text><view class="filter-chevron"/><view v-if="filterOpen" class="menu"><text :class="{selected:filter==='reviewing'}" @tap.stop="setFilter('reviewing')">审核中 <i>{{ counts.reviewing }}</i></text><text :class="{selected:filter==='rejected'}" @tap.stop="setFilter('rejected')">未通过 <i>{{ counts.rejected }}</i></text></view></view></view>
      <view v-if="filtered.length" class="campaign-list">
        <view v-for="item in filtered" :key="item.id" class="campaign-card" :class="item.status" @tap="editCampaign(item)">
          <view class="card-main"><view class="cover" :class="item.theme"><image v-if="item.images?.[0]" :src="item.images[0]" mode="aspectFill"/><text v-else>{{ themeIcon(item.theme) }}</text><i>{{ item.badge||'套餐' }}</i></view><view class="campaign-info"><view class="name-row"><text>{{ item.name }}</text><text class="status" :class="item.status">{{ statusMeta(item).label }}</text></view><view class="price"><text>¥{{ item.price }}</text><text>¥{{ item.originalPrice }}</text></view><view class="meta"><text>🔥 {{ item.sales }} 单</text><text>·</text><text>◉ {{ item.views }} 次</text><text class="rate">▣ {{ item.partnerRate }}% 奖励</text></view></view></view>
          <view v-if="item.status==='rejected'" class="rejection"><text>×</text><text><b>驳回原因：</b>{{ item.rejectionReason }}</text></view>
          <view v-if="item.status==='rejected'" class="actions"><button @tap.stop="removeCampaign(item)">删除套餐</button><button @tap.stop="editCampaign(item)">修改并提交</button></view>
        </view>
      </view>
      <view v-else class="empty"><text>◇</text><text>暂无相关套餐</text><text>尝试切换筛选条件或新建套餐</text></view>
    </view>
    <merchant-tabbar active="campaign"/>
  </view>
</template>

<script setup>
import { computed, ref } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import MerchantTabbar from '../../components/merchant-tabbar.vue'
import { campaignStatusMeta, useMerchantCampaigns } from '../../composables/use-merchant-campaigns'
import { enforcePortal } from '../../core/route-guard'
const {campaigns,counts,deleteCampaign}=useMerchantCampaigns()
const keyword=ref(''),filter=ref('all'),filterOpen=ref(false)
const filtered=computed(()=>campaigns.value.filter(item=>(filter.value==='all'||item.status===filter.value)&&(!keyword.value||item.name.includes(keyword.value))))
const filterLabel=computed(()=>filter.value==='reviewing'?'审核中':filter.value==='rejected'?'未通过':'筛选')
onLoad(()=>enforcePortal('merchant'))
function setFilter(value){filter.value=value;filterOpen.value=false}
function statusMeta(item){return campaignStatusMeta[item.status]||campaignStatusMeta.draft}
function themeIcon(theme){return{dinner:'🥂',sushi:'🍣',grill:'🔥',dessert:'🍰',seafood:'🦞'}[theme]||'🍽'}
function createCampaign(){uni.navigateTo({url:'/pages/merchant/package-form'})}
function editCampaign(item){uni.navigateTo({url:`/pages/merchant/package-form?id=${item.id}`})}
function goNotifications(){uni.navigateTo({url:'/pages/merchant/notifications'})}
function removeCampaign(item){uni.showModal({title:'删除套餐',content:`确认删除“${item.name}”吗？`,confirmText:'删除',confirmColor:'#d44c46',success:({confirm})=>{if(!confirm)return;deleteCampaign(item.id);uni.showToast({title:'套餐已删除',icon:'success'})}})}
</script>

